SELECT  FROM standard_review
WHERE owner_id=#{owner} AND question_id=#{questionId} AND question_version_id=#{versionId}
AND status=#{status}
AND id > #{cursor}
ORDER BY id ASC LIMIT #{pageSize}


SELECT  FROM standard_review_revision
WHERE owner_id=#{owner} AND review_id=#{id}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{pageSize}

SELECT owner_id,review_id,revision,checkpoint_id,position_index,decision FROM standard_review_checkpoint
WHERE owner_id=#{owner} AND review_id=#{id} AND revision=#{revision}
ORDER BY position_index ASC LIMIT 30

SELECT MAX(revision) FROM standard_review_checkpoint
WHERE owner_id=#{owner} AND review_id=#{reviewId} AND checkpoint_id=#{checkpointId}
  AND revision < #{beforeExclusive}

