UPDATE standard_review SET revision=#{row.revision},status=#{row.status},updated_at=#{row.updatedAt}
WHERE owner_id=#{row.ownerId} AND id=#{row.id} AND question_id=#{row.questionId}
  AND question_version_id=#{row.versionId} AND revision=#{expected} AND status='ACTIVE'
  AND #{expected} < 9007199254740991 AND #{row.revision}=revision+1
  AND #{row.updatedAt} >= updated_at
